public class LegacySummaryObservation {
 public static String observe(Boolean defaults){
  ProbeTile__c p=(ProbeTile__c)SummaryFactoryAdapter.make(defaults);p.Name='Summary seed';
  Map<String,Object> result=new Map<String,Object>{'defaults'=>defaults,'beforeCount'=>p.DotCount__c};
  SummaryInsertService.save(p);result.put('afterCount',p.DotCount__c);
  ProbeTile__c q=[SELECT DotCount__c,(SELECT Id FROM Dots__r) FROM ProbeTile__c WHERE Id=:p.Id];
  result.put('queriedCount',q.DotCount__c);result.put('childListNull',q.Dots__r==null);result.put('childCount',q.Dots__r.size());
  result.put('count',[SELECT COUNT() FROM ProbeDot__c WHERE ParentTile__c=:p.Id]);
  AggregateResult a=[SELECT SUM(Amount__c) total FROM ProbeDot__c WHERE ParentTile__c=:p.Id];result.put('sum',a.get('total'));
  return JSON.serialize(result);
 }
}

